    library(r2d3)
    library(data.table)
    
    # Define UI for application that shows the D3 plot and returns the updated correlation:
    ui <- fluidPage(
      titlePanel(""),
      sidebarLayout(
       
        sidebarPanel(style = "background-color: #ffffff; border-color: gray92 ; border-width: 2px", width = 3, 
                     numericInput("npp",
                                 "number of 'participants'",
                                 value = 8),
